import { expect, test } from "vitest";
import { checkGenerated, type GeneratedFile } from "./check.ts";

const artifact = "/repo/packages/web/src/__generated__/ProjectsQuery.graphql.ts";
const schema = "/repo/packages/web/schema.graphql";
const HEADER = "/**\n * @generated SignedSource<<abc123>>\n */\n";
const SCHEMA_TEXT =
  "# Generated by @hns/server (buildSchemaSdl). Do not edit by hand.\n# Regenerate with npm run codegen.\ntype Query {\n  ok: Boolean\n}\n";

const files = (): GeneratedFile[] => [
  { path: artifact, text: HEADER + "export type X = string;\n" },
  { path: schema, text: SCHEMA_TEXT },
];

test("generated files with their headers pass", () => {
  expect(checkGenerated(files())).toStrictEqual([]);
});

// Catches: a hand-written or truncated artifact that the compiler would happily read.
test("an artifact without the generated header is refused", () => {
  const broken = files().map((file) =>
    file.path === artifact ? { ...file, text: "export type X = string;\n" } : file,
  );
  expect(checkGenerated(broken)).toStrictEqual([
    artifact + " has no @generated header; run npm run codegen",
  ]);
});

// Catches: an empty artifact directory, which means relay-compiler never ran.
test("an empty artifact directory is refused", () => {
  const onlySchema = files().filter((file) => file.path === schema);
  expect(checkGenerated(onlySchema)).toStrictEqual([
    "packages/web/src/__generated__ is empty; run npm run codegen",
  ]);
});

// Catches: a schema that lost the regeneration command, so the next reader cannot rebuild it.
test("a schema without the command or header is refused", () => {
  const broken = files().map((file) =>
    file.path === schema ? { ...file, text: "type Query {\n  ok: Boolean\n}\n" } : file,
  );
  expect(checkGenerated(broken)).toStrictEqual([
    "packages/web/schema.graphql does not start with the generated header",
    "packages/web/schema.graphql does not name the regeneration command",
  ]);
});

// Catches: a missing schema file, which codegen always writes.
test("a missing schema is refused", () => {
  const noSchema = files().filter((file) => file.path !== schema);
  expect(checkGenerated(noSchema)).toStrictEqual([
    "packages/web/schema.graphql is missing; run npm run codegen",
  ]);
});
